"""Report raw counts and the limits of the two separate splits."""
from pathlib import Path
import json
R=Path(__file__).resolve().parent
labels={'baseline':'Обученная политика','one_step':'Пропустить последнее отклонённое направление один раз','pose_set':'Хранить отклонения при текущей позиции'}
def f(x):return f'{x:.2f}'.replace('.',',')
def inter(x,scale=1):return '['+', '.join(f(v*scale) for v in x)+']'
def main():
    d=json.loads((R/'results.json').read_bytes());lines=['# Память об отвергнутых командах в текстовом ALFWorld','',
    'В предыдущем опыте агент освоил приоритеты поиска предметов по 39 тренировочным играм. При проверке только по тексту он десять раз не завершил задачу после повторов перехода с ответом «Nothing happens.». Мы проверили, достаточно ли один раз пропустить отвергнутую команду или полезно помнить все такие направления до смены позиции. Во всех условиях доступны те же обученные приоритеты, общий список осмотренных мест, грамматика команд, наблюдаемая позиция и инвентарь. Работа выполнялась локально в симуляторе на CPU. LLM не вызывалась.','',
    'Правило записи срабатывало только на точный ответ «Nothing happens.» вслед за собственной командой go to. Одношаговый вариант исключал это направление на следующем выборе. Вариант с набором исключал все отвергнутые назначения из этой позиции, а успешный переход очищал набор. С ценой в один шаг учитывались каждая отклонённая попытка и команда look при отсутствии доступного по правилу направления. Меню допустимых действий в TextWorld отключено. Системная отметка победы использована для внешней оценки и остановки, а действия восстанавливаются только по видимому тексту.','',
    'В 134 играх valid_unseen прежние результаты послужили основанием для гипотезы. Здесь её проверка ретроспективна. Вторая выборка valid_seen содержит 140 новых эпизодов из знакомых планировок. До просмотра результатов этого текстового теста заранее зафиксированы алгоритмы, частоты и идентификаторы обеих выборок. Предыдущие исследования этой рабочей группы на иных интерфейсах могли использовать те же миры. Все три условия физически запущены на valid_seen. Для valid_unseen повторно взяты 134 хешированных исходных траектории, остальные 268 разыграны заново. Всего получено 688 дополнительных физических разыгрываний, в трёхстороннем сравнении участвуют 822. [ALFWorld](https://arxiv.org/abs/2010.03768)','']
    for split,title in [('valid_unseen','134 игры, на которых обнаружена проблема'),('valid_seen','140 заранее отложенных игр')]:
        z=d[split];lines+=['## '+title,'','| Политика | Победы | Действия¹ | Попытки go to с отказом | Повторные отказы² | Пик числа записанных направлений |','|---|---:|---:|---:|---:|---:|']
        for a in labels:
            t=z['arms'][a];lines.append(f"| {labels[a]} | {t['wins']} / {z['n']} | {f(t['mean_capped_steps'])} | {t['rejected']} | {t['repeat_rejected']} | {t['peak_negative_entries']} |")
        lines+=['','¹ Среднее число действий, незавершённая задача стоит 50. ² Повтор идентичной пары (исходная позиция, назначение) после предшествующего отказа в пределах эпизода. После смены позиции сам агент может забыть старую запись.','',
        '| Сравнение | Выигрыши / проигрыши / ничьи | Разность побед, п.п. | 95% по играм | 95% по планировкам | Одинаковые цепочки действий |',
        '|---|---:|---:|---:|---:|---:|']
        for k in ['one_step-baseline','pose_set-baseline','pose_set-one_step']:
            x=z['contrasts'][k];s=x['success'];a,b=k.split('-')
            lines.append(f"| {labels[a]} − {labels[b]} | {s['positive']} / {s['negative']} / {s['ties']} | {f(100*s['delta'])} | {inter(s['task_boot95'],100)} | {inter(s['floorplan_boot95'],100)} | {x['identical_actions']} / {z['n']} |")
        lines+=['','| Бюджет действий | Обычная | Одношаговый пропуск | Набор |','|---|---:|---:|---:|']
        for h in [10,20,30,40,50]:lines.append('| '+str(h)+' | '+' | '.join(str(z['horizon'][str(h)][a]) for a in labels)+' |')
        x=z['contrasts']['pose_set-one_step'];y=z['contrasts']['one_step-baseline'];n=z['floorplans']
        lines+=['',f"Планировок в выборке — {n}. Для интервалов использованы 5 000 повторных парных выборок отдельно по играм и по планировкам. Разность затрат набора и одношагового пропуска — {f(x['cost']['delta'])} действия на игру, 95% по играм {inter(x['cost']['task_boot95'])}. У одношагового пропуска против исходной политики разность {f(y['cost']['delta'])} действия, 95% по играм {inter(y['cost']['task_boot95'])}. Точный знаковый тест по дискордантным итогам задач набора против одношагового контроля даёт p={x['discordant_sign_p']:.4g}. При малом числе планировок кластерный интервал груб. Меньшие бюджеты получены отсечением физически исполненных траекторий.",'']
    external=d['valid_seen'];explore=d['valid_unseen']
    lines+=['## Как интерпретировать','',
    f"На заранее отложенных задачах одношаговая реакция на отказ увеличила число побед с {external['arms']['baseline']['wins']} до {external['arms']['one_step']['wins']} из {external['n']}. Набор отказов дал те же исходы и число действий в каждой игре. На выборке обнаружения все {explore['n']} цепочки команд двух способов обработки отказов полностью совпали. На внешней выборке в единственной расходящейся игре набор после двух отвергнутых переходов исследовал полку и действительно поднял CD, тогда как одношаговый вариант чередовал два недоступных направления. Оба варианта исчерпали бюджет. На внешней выборке суммарное число отвергнутых переходов снизилось с {external['arms']['one_step']['rejected']} до {external['arms']['pose_set']['rejected']}, при том же числе побед и средних затратах. Добавленная сложность полезна для устранения повторных неудачных действий, но её самостоятельное преимущество по решению задач в данной проверке отсутствует.",'',
    'Различия между исходной политикой и одношаговым пропуском измеряют пользу реакции на отказ. Дополнительная ценность сохранения нескольких отрицательных фактов измеряется только сравнением с одношаговым правилом. Совпадение цепочек действий при различных внутренних правилах означает, что данное окружение не проявило соответствующее различие на этих эпизодах. Нулевая разность успехов при 50 шагах может сочетаться с разной стоимостью и успехом при меньшем бюджете.','',
    'Чтобы переносить вывод на память кодового агента, требуется проверка на его реальных повторных действиях (например, повторный запуск уже отклонённой команды с неизменившимися предпосылками), на конечном успехе и затратах при одинаковом бюджете. Здесь исходный механизм навигации и грамматика известны разработчику. Набор интерактивных ALFWorld-игр позволяет измерить поведение политики с объективным сигналом, но остаётся доменно-специфической моделью агентной работы.',
    '', '## Проверка журнала','',
    'Команда `python verify.py --check` работает автономно в этом каталоге, без Docker или моделей. Она проверяет входные хеши, заново выбирает каждую команду каждой политики из текстов, сверяет флаги и пересчитывает метрики. Файлы results.json, per_episode.csv, divergences.json содержат показатели, построчные результаты и первые различия между двумя вариантами памяти при их наличии. Подробности физического повтора — в REPRODUCE.md.']
    (R/'summary_ru.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
if __name__=='__main__':main()
